catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    var sn_appointment = g_form.getValue("sn_appointment");
    var sn_appointmentJSON = JSON.parse(sn_appointment);
    //Type appropriate comment here, and begin script below
    if (newValue == "true" && sn_appointmentJSON && sn_appointmentJSON.config) {

        sn_appointmentJSON.config.service_config.mandatory = "0";
        g_form.setValue("sn_appointment", JSON.stringify(sn_appointmentJSON));
        g_form.setDisplay('sn_appointment_macro', false);


    } else {

        sn_appointmentJSON.config.service_config.mandatory = "1";
        g_form.setValue("sn_appointment", JSON.stringify(sn_appointmentJSON));
        g_form.setDisplay('sn_appointment_macro', true);

    }


}
